#include <iostream>
using namespace std;

int l[100], r[100], val[100], idx = 1;

void preorder(int u) {
    if (!u) return;
    cout << val[u] << " ";
    preorder(l[u]);
    preorder(r[u]);
}

void inorder(int u) {
    if (!u) return;
    inorder(l[u]);
    cout << val[u] << " ";
    inorder(r[u]);
}

int main() {
    val[1] = 1; l[1] = 2; r[1] = 3;
    val[2] = 2; val[3] = 3;
    preorder(1); cout << endl;
    inorder(1); cout << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

vector<int> ch[100];
int dep[100];

void dfs(int u, int d) {
    dep[u] = d;
    for (int v : ch[u]) dfs(v, d + 1);
}

int main() {
    int n;
    cin >> n;
    for (int i = 2; i <= n; i++) {
        int p;
        cin >> p;
        ch[p].push_back(i);
    }
    dfs(1, 0);
    for (int i = 1; i <= n; i++)
        cout << i << ": dep=" << dep[i] << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

vector<int> ch[100001];
int dep[100001], fa[100001][20];

void dfs(int u, int p) {
    fa[u][0] = p;
    dep[u] = dep[p] + 1;
    for (int j = 1; j < 20; j++)
        fa[u][j] = fa[fa[u][j-1]][j-1];
    for (int v : ch[u]) if (v != p) dfs(v, u);
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    for (int j = 19; j >= 0; j--)
        if (dep[fa[u][j]] >= dep[v]) u = fa[u][j];
    if (u == v) return u;
    for (int j = 19; j >= 0; j--)
        if (fa[u][j] != fa[v][j]) { u = fa[u][j]; v = fa[v][j]; }
    return fa[u][0];
}
